import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  onSessionCreated: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSessionCreated }) => {
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  // 密碼管理相關
  const [currentRefereePassword, setCurrentRefereePassword] = useState('');
  const [newRefereePassword, setNewRefereePassword] = useState('');
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSessions();
    loadSettings();
  }, []);

  const loadSessions = async () => {
    const data = await storageService.getSessions();
    setSessions(data);
  };

  const loadSettings = async () => {
    const settings = await storageService.getSettings();
    if (settings && settings.refereePassword) {
      setCurrentRefereePassword(settings.refereePassword);
    }
  };

  const toggleSessionStatus = async (session: MatchSession) => {
    const newStatus = session.status === MatchStatus.OPEN ? MatchStatus.CLOSED : MatchStatus.OPEN;
    await storageService.updateSession({ ...session, status: newStatus });
    await loadSessions();
  };

  const handleUpdatePassword = async () => {
    if (!newRefereePassword) return alert('請輸入新密碼');
    if (newRefereePassword.length < 4) return alert('密碼長度建議至少 4 位');

    setIsUpdatingPassword(true);
    try {
      await storageService.updateRefereePassword(newRefereePassword);
      alert('裁判登入密碼已成功更新！');
      setCurrentRefereePassword(newRefereePassword);
      setNewRefereePassword('');
    } catch (e) {
      alert('密碼更新失敗，請檢查網路。');
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    if (names.length > 0) {
      setReferees(prev => {
        const nextReferees = [...prev];
        names.forEach(name => {
          if (!nextReferees.includes(name)) nextReferees.push(name);
        });
        return nextReferees;
      });
      setRefereeInput('');
    }
  };

  const removeReferee = (name: string) => {
    setReferees(referees.filter(r => r !== name));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { 
      tableNumber: nextNum, 
      player1: { id: '', name: '' }, 
      player2: { id: '', name: '' }, 
      result: GameResult.PENDING 
    }]);
  };

  const updateTable = (index: number, field: string, value: any) => {
    const newTables = [...tables];
    const target = { ...newTables[index] };
    if (field === 'p1Id') target.player1 = { ...target.player1!, id: value };
    else if (field === 'p1Name') target.player1 = { ...target.player1!, name: value };
    else if (field === 'p2Id') target.player2 = { ...target.player2!, id: value };
    else if (field === 'p2Name') target.player2 = { ...target.player2!, name: value };
    else if (field === 'tableNumber') target.tableNumber = parseInt(value) || 0;
    newTables[index] = target;
    setTables(newTables);
  };

  const removeTable = (index: number) => {
    setTables(tables.filter((_, i) => i !== index));
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        // 根據用戶需求更新欄位映射：
        // 抬號 -> tableNumber
        // 先手編號 -> player1.id
        // 先手姓名 -> player1.name
        // 後手編號 -> player2.id
        // 後手姓名 -> player2.name
        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: parseInt(row['抬號'] || row['桌號'] || row['Table'] || (idx + 1)),
          player1: { 
            id: String(row['先手編號'] || row['先手ID'] || row['P1 ID'] || ''), 
            name: String(row['先手姓名'] || row['P1 Name'] || '') 
          },
          player2: { 
            id: String(row['後手編號'] || row['後手ID'] || row['P2 ID'] || ''), 
            name: String(row['後手姓名'] || row['P2 Name'] || '') 
          },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗，請確認檔案格式是否正確。');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportExcel = (session: MatchSession) => {
    const exportData = session.tables.map(t => ({
      '抬號': t.tableNumber,
      '先手編號': t.player1.id,
      '先手姓名': t.player1.name,
      '後手編號': t.player2.id,
      '後手姓名': t.player2.name,
      '結果': t.result,
      '送出裁判': t.submittedBy || '',
      '更新時間': t.updatedAt ? new Date(t.updatedAt).toLocaleString() : ''
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '比賽結果');
    XLSX.writeFile(workbook, `${session.title}_比賽結果.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入場次標題');
    if (referees.length === 0) return alert('請至少輸入一位裁判人員');

    const sessionData = {
      title,
      referees,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      });
      alert('場次已成功建立並同步雲端');
    }
    resetForm();
    onSessionCreated();
    await loadSessions();
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('確定刪除此比賽場次？此動作將同步影響所有設備。')) {
      await storageService.deleteSession(id);
      await loadSessions();
      onSessionCreated();
      if (editingSessionId === id) resetForm();
    }
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      {/* 系統安全設定 */}
      <section className="bg-white rounded-2xl shadow-sm border border-red-100 overflow-hidden">
        <div className="bg-red-50 px-6 py-4 border-b border-red-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-red-800 flex items-center">
            <i className="fas fa-user-shield mr-2"></i>
            系統帳號權限管理
          </h2>
        </div>
        <div className="p-6">
          <div className="max-w-md space-y-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">當前裁判登入密碼</p>
                <p className="text-2xl font-black text-slate-700 tracking-widest">
                  {currentRefereePassword || '載入中...'}
                </p>
              </div>
              <div className="bg-white p-2 rounded-lg shadow-sm">
                <i className="fas fa-key text-amber-500 text-xl"></i>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">更新裁判登入密碼</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={newRefereePassword}
                  onChange={(e) => setNewRefereePassword(e.target.value)}
                  className="flex-grow px-4 py-2 border rounded-xl focus:ring-2 focus:ring-red-500 outline-none transition"
                  placeholder="輸入新密碼..."
                />
                <button 
                  onClick={handleUpdatePassword}
                  disabled={isUpdatingPassword}
                  className="bg-red-600 text-white px-6 rounded-xl font-bold hover:bg-red-700 transition disabled:bg-gray-400"
                >
                  {isUpdatingPassword ? '同步中...' : '確認更改'}
                </button>
              </div>
              <p className="mt-2 text-xs text-gray-400">※ 更改後，所有使用「裁判專區」的人員需使用新密碼登入。</p>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center">
            <i className="fas fa-tasks text-indigo-500 mr-2"></i>
            現有比賽場次管理
          </h2>
          <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">
            共 {sessions.length} 場
          </span>
        </div>
        <div className="divide-y divide-gray-100">
          {sessions.length > 0 ? sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow text-center md:text-left">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <div className="flex flex-wrap justify-center md:justify-start gap-3 mt-2 items-center">
                  {/* 開放/截止切換按鈕 */}
                  <button 
                    onClick={() => toggleSessionStatus(session)}
                    className={`flex items-center space-x-2 px-3 py-1 rounded-full text-xs font-bold transition-all ${
                      session.status === MatchStatus.OPEN 
                        ? 'bg-green-500 text-white shadow-sm shadow-green-200' 
                        : 'bg-red-500 text-white shadow-sm shadow-red-200'
                    }`}
                  >
                    <i className={`fas ${session.status === MatchStatus.OPEN ? 'fa-lock-open' : 'fa-lock'}`}></i>
                    <span>{session.status === MatchStatus.OPEN ? '開放傳送中' : '已截止傳送'}</span>
                    <span className="bg-white bg-opacity-30 px-1.5 py-0.5 rounded text-[9px]">點擊切換</span>
                  </button>
                  <span className="text-[10px] text-gray-400 bg-gray-100 px-2 py-1 rounded">桌數: {session.tables.length}</span>
                </div>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => handleExportExcel(session)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="匯出 Excel">
                  <i className="fas fa-file-excel text-xl"></i>
                </button>
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition" title="修改">
                  <i className="fas fa-edit text-xl"></i>
                </button>
                <button onClick={() => handleDelete(session.id)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-lg transition" title="刪除">
                  <i className="fas fa-trash-alt text-xl"></i>
                </button>
              </div>
            </div>
          )) : (
            <div className="py-20 text-center text-gray-400 italic">尚未建立任何比賽場次</div>
          )}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center">
          <i className={`fas ${editingSessionId ? 'fa-pen-nib text-amber-500' : 'fa-plus-circle text-indigo-500'} mr-3`}></i>
          {editingSessionId ? '編輯比賽場次' : '建立全新比賽場次'}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input 
                type="text" 
                value={title} 
                onChange={(e) => setTitle(e.target.value)} 
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                placeholder="例如：2024 夏季杯複賽" 
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">裁判名單 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={refereeInput} 
                  onChange={(e) => setRefereeInput(e.target.value)} 
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addReferee())}
                  className="flex-grow px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                  placeholder="輸入姓名並按新增" 
                />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-slate-700 transition">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 pt-2">
                {referees.map(r => (
                  <span key={r} className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {r}
                    <button type="button" onClick={() => removeReferee(r)} className="ml-2 hover:text-red-500">
                      <i className="fas fa-times-circle"></i>
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div className="flex flex-col">
                <h3 className="text-lg font-bold text-slate-800">桌次與對手設定</h3>
                <p className="text-[10px] text-gray-400">Excel 支援標題：抬號、先手編號、先手姓名、後手編號、後手姓名</p>
              </div>
              <div className="flex space-x-3">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} accept=".xlsx,.xls" className="hidden" />
                <button type="button" onClick={() => fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-100 transition">
                  <i className="fas fa-file-import mr-2"></i>匯入 Excel
                </button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-100 transition">
                  <i className="fas fa-plus mr-2"></i>新增一桌
                </button>
              </div>
            </div>

            <div className="overflow-x-auto border rounded-2xl">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr className="text-left text-slate-500 font-bold uppercase">
                    <th className="px-4 py-3 w-20">桌號 (抬號)</th>
                    <th className="px-4 py-3">先手 (編號 / 姓名)</th>
                    <th className="px-4 py-3">後手 (編號 / 姓名)</th>
                    <th className="px-4 py-3 w-16 text-center">刪</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((table, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3">
                        <input type="number" value={table.tableNumber} onChange={(e) => updateTable(idx, 'tableNumber', e.target.value)} className="w-full p-2 border rounded-lg focus:ring-1 focus:ring-indigo-400 outline-none" />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="編號" value={table.player1?.id} onChange={(e) => updateTable(idx, 'p1Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player1?.name} onChange={(e) => updateTable(idx, 'p1Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="編號" value={table.player2?.id} onChange={(e) => updateTable(idx, 'p2Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player2?.name} onChange={(e) => updateTable(idx, 'p2Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button type="button" onClick={() => removeTable(idx)} className="text-red-400 hover:text-red-600 p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t">
            <button type="submit" className={`flex-grow py-4 rounded-2xl font-black text-lg text-white shadow-xl transition active:scale-95 ${editingSessionId ? 'bg-amber-500 hover:bg-amber-600 shadow-amber-200' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'}`}>
              {editingSessionId ? '確認儲存修改' : '建立比賽場次'}
            </button>
            {editingSessionId && (
              <button type="button" onClick={resetForm} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-bold hover:bg-slate-200 transition">
                取消編輯
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { UserRole, MatchSession } from './types.ts';
import { storageService } from './services/storage.ts';
import AdminPanel from './components/AdminPanel.tsx';
import RefereePanel from './components/RefereePanel.tsx';
import ResultsBoard from './components/ResultsBoard.tsx';
import LoginModal from './components/LoginModal.tsx';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [activeTab, setActiveTab] = useState<'admin' | 'referee' | 'results'>('results');
  const [showLogin, setShowLogin] = useState<UserRole | null>(null);
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const isCloud = storageService.isCloudEnabled();

  // 使用實時訂閱模式
  useEffect(() => {
    const unsubscribe = storageService.subscribeSessions((updatedSessions) => {
      setSessions(updatedSessions);
    });
    return () => unsubscribe();
  }, []);

  const handleLogin = (targetRole: UserRole) => {
    if (role === targetRole) {
      if (targetRole === UserRole.ADMIN) setActiveTab('admin');
      if (targetRole === UserRole.REFEREE) setActiveTab('referee');
      return;
    }
    setShowLogin(targetRole);
  };

  const handleLogout = () => {
    setRole(UserRole.GUEST);
    setActiveTab('results');
  };

  const onLoginSuccess = (successRole: UserRole) => {
    setRole(successRole);
    setShowLogin(null);
    setActiveTab(successRole === UserRole.ADMIN ? 'admin' : 'referee');
  };

  const getRoleLabel = (r: UserRole) => {
    switch (r) {
      case UserRole.ADMIN: return '後台人員';
      case UserRole.REFEREE: return '裁判人員';
      default: return '一般選手/訪客';
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-indigo-700 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setActiveTab('results')}>
            <i className="fas fa-trophy text-2xl text-yellow-400"></i>
            <h1 className="text-xl font-bold tracking-tight hidden sm:block">比賽紀錄系統</h1>
            {isCloud && (
              <span className="ml-2 flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-2 w-2 rounded-full bg-green-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
              </span>
            )}
          </div>

          <div className="flex items-center space-x-1 sm:space-x-4">
            <nav className="flex space-x-1">
              <button 
                onClick={() => setActiveTab('results')}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'results' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                比賽結果
              </button>
              <button 
                onClick={() => handleLogin(UserRole.REFEREE)}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'referee' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                裁判專區
              </button>
              <button 
                onClick={() => handleLogin(UserRole.ADMIN)}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'admin' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                後台管理
              </button>
            </nav>

            <div className="h-8 w-[1px] bg-indigo-500 mx-2 hidden sm:block"></div>

            <div className="flex items-center space-x-2">
               {role !== UserRole.GUEST && (
                 <button 
                  onClick={handleLogout}
                  className="bg-red-500 hover:bg-red-600 text-white w-8 h-8 rounded-full flex items-center justify-center transition shadow-sm"
                 >
                   <i className="fas fa-sign-out-alt text-xs"></i>
                 </button>
               )}
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8">
        <div className="mb-4 flex justify-between items-center text-xs">
          <div className="flex items-center text-gray-400">
            <i className={`fas fa-cloud mr-1 ${isCloud ? 'text-green-500' : 'text-gray-300'}`}></i>
            {isCloud ? '雲端即時同步中' : '本地儲存模式'}
          </div>
          <div className="font-bold text-gray-500">
            {getRoleLabel(role)}
          </div>
        </div>

        {activeTab === 'results' && (
          <ResultsBoard 
            sessions={sessions} 
            userRole={role} 
            onRefresh={() => {}} 
          />
        )}

        {activeTab === 'admin' && role === UserRole.ADMIN && (
          <AdminPanel sessions={sessions} onSessionCreated={() => {}} />
        )}

        {activeTab === 'referee' && role === UserRole.REFEREE && (
          <RefereePanel sessions={sessions} onResultSubmitted={() => {}} />
        )}

        {(activeTab === 'admin' || activeTab === 'referee') && role !== (activeTab === 'admin' ? UserRole.ADMIN : UserRole.REFEREE) && (
          <div className="text-center py-20 bg-white rounded-2xl shadow-sm border border-gray-100">
            <i className="fas fa-user-lock text-3xl text-indigo-200 mb-6"></i>
            <h2 className="text-2xl font-bold text-gray-800 mb-2">請先登入</h2>
            <button 
              onClick={() => handleLogin(activeTab === 'admin' ? UserRole.ADMIN : UserRole.REFEREE)}
              className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold"
            >
              登入 {activeTab === 'admin' ? '管理員' : '裁判'} 帳號
            </button>
          </div>
        )}
      </main>

      {showLogin && (
        <LoginModal 
          targetRole={showLogin} 
          onClose={() => setShowLogin(null)} 
          onSuccess={onLoginSuccess} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  sessions: MatchSession[];
  onSessionCreated: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ sessions, onSessionCreated }) => {
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  // 密碼管理相關
  const [currentRefereePassword, setCurrentRefereePassword] = useState('');
  const [newRefereePassword, setNewRefereePassword] = useState('');
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    const settings = await storageService.getSettings();
    if (settings && settings.refereePassword) {
      setCurrentRefereePassword(settings.refereePassword);
    }
  };

  const toggleSessionStatus = async (session: MatchSession) => {
    const newStatus = session.status === MatchStatus.OPEN ? MatchStatus.CLOSED : MatchStatus.OPEN;
    await storageService.updateSession({ ...session, status: newStatus });
  };

  const handleUpdatePassword = async () => {
    if (!newRefereePassword) return alert('請輸入新密碼');
    if (newRefereePassword.length < 4) return alert('密碼長度建議至少 4 位');

    setIsUpdatingPassword(true);
    try {
      await storageService.updateRefereePassword(newRefereePassword);
      alert('裁判登入密碼已成功更新！');
      setCurrentRefereePassword(newRefereePassword);
      setNewRefereePassword('');
    } catch (e) {
      alert('密碼更新失敗，請檢查網路。');
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    if (names.length > 0) {
      setReferees(prev => {
        const nextReferees = [...prev];
        names.forEach(name => {
          if (!nextReferees.includes(name)) nextReferees.push(name);
        });
        return nextReferees;
      });
      setRefereeInput('');
    }
  };

  const removeReferee = (name: string) => {
    setReferees(referees.filter(r => r !== name));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { 
      tableNumber: nextNum, 
      player1: { id: '', name: '' }, 
      player2: { id: '', name: '' }, 
      result: GameResult.PENDING 
    }]);
  };

  const updateTable = (index: number, field: string, value: any) => {
    const newTables = [...tables];
    const target = { ...newTables[index] };
    if (field === 'p1Id') target.player1 = { ...target.player1!, id: value };
    else if (field === 'p1Name') target.player1 = { ...target.player1!, name: value };
    else if (field === 'p2Id') target.player2 = { ...target.player2!, id: value };
    else if (field === 'p2Name') target.player2 = { ...target.player2!, name: value };
    else if (field === 'tableNumber') target.tableNumber = parseInt(value) || 0;
    newTables[index] = target;
    setTables(newTables);
  };

  const removeTable = (index: number) => {
    setTables(tables.filter((_, i) => i !== index));
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: parseInt(row['抬號'] || row['桌號'] || row['Table'] || (idx + 1)),
          player1: { 
            id: String(row['先手編號'] || row['先手ID'] || row['P1 ID'] || ''), 
            name: String(row['先手姓名'] || row['P1 Name'] || '') 
          },
          player2: { 
            id: String(row['後手編號'] || row['後手ID'] || row['P2 ID'] || ''), 
            name: String(row['後手姓名'] || row['P2 Name'] || '') 
          },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗，請確認檔案格式是否正確。');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportExcel = (session: MatchSession) => {
    const exportData = session.tables.map(t => ({
      '抬號': t.tableNumber,
      '先手編號': t.player1.id,
      '先手姓名': t.player1.name,
      '後手編號': t.player2.id,
      '後手姓名': t.player2.name,
      '結果': t.result,
      '送出裁判': t.submittedBy || '',
      '更新時間': t.updatedAt ? new Date(t.updatedAt).toLocaleString() : ''
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '比賽結果');
    XLSX.writeFile(workbook, `${session.title}_比賽結果.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入場次標題');
    if (referees.length === 0) return alert('請至少輸入一位裁判人員');

    const sessionData = {
      title,
      referees,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      });
      alert('場次已成功建立並同步雲端');
    }
    resetForm();
    onSessionCreated();
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('確定刪除此比賽場次？此動作將同步影響所有設備。')) {
      try {
        await storageService.deleteSession(id);
        // 刪除成功後，UI 會因為 App.tsx 的即時訂閱自動更新
        if (editingSessionId === id) resetForm();
      } catch (error) {
        alert('刪除失敗，請檢查網路狀態');
      }
    }
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      {/* 系統安全設定 */}
      <section className="bg-white rounded-2xl shadow-sm border border-red-100 overflow-hidden">
        <div className="bg-red-50 px-6 py-4 border-b border-red-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-red-800 flex items-center">
            <i className="fas fa-user-shield mr-2"></i>
            系統帳號權限管理
          </h2>
        </div>
        <div className="p-6">
          <div className="max-w-md space-y-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">當前裁判登入密碼</p>
                <p className="text-2xl font-black text-slate-700 tracking-widest">
                  {currentRefereePassword || '載入中...'}
                </p>
              </div>
              <div className="bg-white p-2 rounded-lg shadow-sm">
                <i className="fas fa-key text-amber-500 text-xl"></i>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">更新裁判登入密碼</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={newRefereePassword}
                  onChange={(e) => setNewRefereePassword(e.target.value)}
                  className="flex-grow px-4 py-2 border rounded-xl focus:ring-2 focus:ring-red-500 outline-none transition"
                  placeholder="輸入新密碼..."
                />
                <button 
                  onClick={handleUpdatePassword}
                  disabled={isUpdatingPassword}
                  className="bg-red-600 text-white px-6 rounded-xl font-bold hover:bg-red-700 transition disabled:bg-gray-400"
                >
                  {isUpdatingPassword ? '同步中...' : '確認更改'}
                </button>
              </div>
              <p className="mt-2 text-xs text-gray-400">※ 更改後，所有使用「裁判專區」的人員需使用新密碼登入。</p>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center">
            <i className="fas fa-tasks text-indigo-500 mr-2"></i>
            現有比賽場次管理
          </h2>
          <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">
            共 {sessions.length} 場
          </span>
        </div>
        <div className="divide-y divide-gray-100">
          {sessions.length > 0 ? sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow text-center md:text-left">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <div className="flex flex-wrap justify-center md:justify-start gap-3 mt-2 items-center">
                  <button 
                    onClick={() => toggleSessionStatus(session)}
                    className={`flex items-center space-x-2 px-3 py-1 rounded-full text-xs font-bold transition-all ${
                      session.status === MatchStatus.OPEN 
                        ? 'bg-green-500 text-white shadow-sm shadow-green-200' 
                        : 'bg-red-500 text-white shadow-sm shadow-red-200'
                    }`}
                  >
                    <i className={`fas ${session.status === MatchStatus.OPEN ? 'fa-lock-open' : 'fa-lock'}`}></i>
                    <span>{session.status === MatchStatus.OPEN ? '開放傳送中' : '已截止傳送'}</span>
                    <span className="bg-white bg-opacity-30 px-1.5 py-0.5 rounded text-[9px]">點擊切換</span>
                  </button>
                  <span className="text-[10px] text-gray-400 bg-gray-100 px-2 py-1 rounded">桌數: {session.tables.length}</span>
                </div>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => handleExportExcel(session)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="匯出 Excel">
                  <i className="fas fa-file-excel text-xl"></i>
                </button>
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition" title="修改">
                  <i className="fas fa-edit text-xl"></i>
                </button>
                <button onClick={() => handleDelete(session.id)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-lg transition" title="刪除">
                  <i className="fas fa-trash-alt text-xl"></i>
                </button>
              </div>
            </div>
          )) : (
            <div className="py-20 text-center text-gray-400 italic">尚未建立任何比賽場次</div>
          )}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center">
          <i className={`fas ${editingSessionId ? 'fa-pen-nib text-amber-500' : 'fa-plus-circle text-indigo-500'} mr-3`}></i>
          {editingSessionId ? '編輯比賽場次' : '建立全新比賽場次'}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input 
                type="text" 
                value={title} 
                onChange={(e) => setTitle(e.target.value)} 
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                placeholder="例如：2024 夏季杯複賽" 
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">裁判名單 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={refereeInput} 
                  onChange={(e) => setRefereeInput(e.target.value)} 
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addReferee())}
                  className="flex-grow px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                  placeholder="輸入姓名並按新增" 
                />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-slate-700 transition">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 pt-2">
                {referees.map(r => (
                  <span key={r} className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {r}
                    <button type="button" onClick={() => removeReferee(r)} className="ml-2 hover:text-red-500">
                      <i className="fas fa-times-circle"></i>
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div className="flex flex-col">
                <h3 className="text-lg font-bold text-slate-800">桌次與對手設定</h3>
                <p className="text-[10px] text-gray-400">Excel 支援標題：抬號、先手編號、先手姓名、後手編號、後手姓名</p>
              </div>
              <div className="flex space-x-3">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} accept=".xlsx,.xls" className="hidden" />
                <button type="button" onClick={() => fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-100 transition">
                  <i className="fas fa-file-import mr-2"></i>匯入 Excel
                </button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-100 transition">
                  <i className="fas fa-plus mr-2"></i>新增一桌
                </button>
              </div>
            </div>

            <div className="overflow-x-auto border rounded-2xl">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr className="text-left text-slate-500 font-bold uppercase">
                    <th className="px-4 py-3 w-20">桌號 (抬號)</th>
                    <th className="px-4 py-3">先手 (編號 / 姓名)</th>
                    <th className="px-4 py-3">後手 (編號 / 姓名)</th>
                    <th className="px-4 py-3 w-16 text-center">刪</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((table, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3">
                        <input type="number" value={table.tableNumber} onChange={(e) => updateTable(idx, 'tableNumber', e.target.value)} className="w-full p-2 border rounded-lg focus:ring-1 focus:ring-indigo-400 outline-none" />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="編號" value={table.player1?.id} onChange={(e) => updateTable(idx, 'p1Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player1?.name} onChange={(e) => updateTable(idx, 'p1Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="編號" value={table.player2?.id} onChange={(e) => updateTable(idx, 'p2Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player2?.name} onChange={(e) => updateTable(idx, 'p2Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button type="button" onClick={() => removeTable(idx)} className="text-red-400 hover:text-red-600 p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t">
            <button type="submit" className={`flex-grow py-4 rounded-2xl font-black text-lg text-white shadow-xl transition active:scale-95 ${editingSessionId ? 'bg-amber-500 hover:bg-amber-600 shadow-amber-200' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'}`}>
              {editingSessionId ? '確認儲存修改' : '建立比賽場次'}
            </button>
            {editingSessionId && (
              <button type="button" onClick={resetForm} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-bold hover:bg-slate-200 transition">
                取消編輯
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

export enum MatchStatus {
  OPEN = 'OPEN',
  CLOSED = 'CLOSED'
}

export enum GameResult {
  PENDING = '待定',
  WIN = '勝',
  LOSS = '負',
  DRAW = '和'
}

export enum UserRole {
  GUEST = 'GUEST',
  ADMIN = 'ADMIN',
  REFEREE = 'REFEREE'
}

export interface PlayerInfo {
  id: string;
  name: string;
}

export interface ScoringConfig {
  win: { p1: number; p2: number };   // 先手勝時的分數
  loss: { p1: number; p2: number };  // 先手負時的分數
  draw: { p1: number; p2: number };  // 和棋時的分數
}

export interface TableMatch {
  tableNumber: number;
  player1: PlayerInfo;
  player2: PlayerInfo;
  assignedReferee?: string;
  result: GameResult;
  submittedBy?: string;
  updatedAt?: string;
}

export interface MatchSession {
  id: string;
  title: string;
  status: MatchStatus;
  referees: string[];
  tables: TableMatch[];
  scoringConfig: ScoringConfig;
  createdAt: string;
}

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult, ScoringConfig } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  sessions: MatchSession[];
  onSessionCreated: () => void;
}

const DEFAULT_SCORING: ScoringConfig = {
  win: { p1: 1, p2: 0 },
  loss: { p1: 0, p2: 1 },
  draw: { p1: 0.5, p2: 0.5 }
};

const AdminPanel: React.FC<AdminPanelProps> = ({ sessions, onSessionCreated }) => {
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [currentRefereePassword, setCurrentRefereePassword] = useState('');
  const [newRefereePassword, setNewRefereePassword] = useState('');
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [scoring, setScoring] = useState<ScoringConfig>(DEFAULT_SCORING);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    const settings = await storageService.getSettings();
    if (settings && settings.refereePassword) {
      setCurrentRefereePassword(settings.refereePassword);
    }
  };

  const toggleSessionStatus = async (session: MatchSession) => {
    const newStatus = session.status === MatchStatus.OPEN ? MatchStatus.CLOSED : MatchStatus.OPEN;
    await storageService.updateSession({ ...session, status: newStatus });
  };

  const handleUpdatePassword = async () => {
    if (!newRefereePassword) return alert('請輸入新密碼');
    if (newRefereePassword.length < 4) return alert('密碼長度建議至少 4 位');
    setIsUpdatingPassword(true);
    try {
      await storageService.updateRefereePassword(newRefereePassword);
      alert('密碼已更新');
      setCurrentRefereePassword(newRefereePassword);
      setNewRefereePassword('');
    } catch (e) {
      alert('更新失敗');
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: parseInt(row['抬號'] || row['桌號'] || row['Table'] || (idx + 1)),
          player1: { 
            id: String(row['先手編號'] || row['先手ID'] || row['P1 ID'] || ''), 
            name: String(row['先手姓名'] || row['P1 Name'] || '') 
          },
          player2: { 
            id: String(row['後手編號'] || row['後手ID'] || row['P2 ID'] || ''), 
            name: String(row['後手姓名'] || row['P2 Name'] || '') 
          },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入標題');

    const sessionData = {
      title,
      referees,
      scoringConfig: scoring,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      } as MatchSession);
      alert('場次已建立');
    }
    resetForm();
    onSessionCreated();
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees);
    setScoring(session.scoringConfig || DEFAULT_SCORING);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null); setScoring(DEFAULT_SCORING);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const updateScoring = (outcome: keyof ScoringConfig, side: 'p1' | 'p2', value: string) => {
    const num = parseFloat(value) || 0;
    setScoring(prev => ({
      ...prev,
      [outcome]: { ...prev[outcome], [side]: num }
    }));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { tableNumber: nextNum, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      <section className="bg-white rounded-2xl shadow-sm border border-red-100 overflow-hidden">
        <div className="bg-red-50 px-6 py-4 border-b border-red-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-red-800 flex items-center">
            <i className="fas fa-user-shield mr-2"></i>系統權限管理
          </h2>
        </div>
        <div className="p-6">
          <div className="max-w-md space-y-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">當前裁判密碼</p>
                <p className="text-2xl font-black text-slate-700 tracking-widest">{currentRefereePassword}</p>
              </div>
              <div className="bg-white p-2 rounded-lg shadow-sm"><i className="fas fa-key text-amber-500 text-xl"></i></div>
            </div>
            <div className="flex space-x-2">
              <input type="text" value={newRefereePassword} onChange={(e) => setNewRefereePassword(e.target.value)} className="flex-grow px-4 py-2 border rounded-xl" placeholder="新密碼..." />
              <button onClick={handleUpdatePassword} disabled={isUpdatingPassword} className="bg-red-600 text-white px-6 rounded-xl font-bold">確認更改</button>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center"><i className="fas fa-tasks text-indigo-500 mr-2"></i>場次管理</h2>
          <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">共 {sessions.length} 場</span>
        </div>
        <div className="divide-y divide-gray-100">
          {sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <button onClick={() => toggleSessionStatus(session)} className={`mt-2 px-3 py-1 rounded-full text-xs font-bold text-white ${session.status === MatchStatus.OPEN ? 'bg-green-500' : 'bg-red-500'}`}>
                  {session.status === MatchStatus.OPEN ? '開放中' : '已截止'}
                </button>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600"><i className="fas fa-edit"></i></button>
                <button onClick={() => storageService.deleteSession(session.id)} className="p-2.5 text-red-500"><i className="fas fa-trash"></i></button>
              </div>
            </div>
          ))}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8"><i className="fas fa-plus-circle text-indigo-500 mr-3"></i>{editingSessionId ? '編輯' : '建立'}場次</h2>
        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} className="w-full px-4 py-3 border rounded-xl" placeholder="例：2024 夏季賽" />
            </div>

            <div className="space-y-4">
              <label className="text-sm font-bold text-slate-600 flex items-center">
                <i className="fas fa-calculator mr-2 text-indigo-400"></i>計分權重設定 (先手/後手得分)
              </label>
              <div className="grid grid-cols-3 gap-4">
                <div className="bg-green-50 p-3 rounded-xl border border-green-100">
                  <p className="text-[10px] font-bold text-green-700 mb-2 uppercase">先勝 (Win)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.win.p1} onChange={(e)=>updateScoring('win','p1',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="先" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.win.p2} onChange={(e)=>updateScoring('win','p2',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="後" />
                  </div>
                </div>
                <div className="bg-red-50 p-3 rounded-xl border border-red-100">
                  <p className="text-[10px] font-bold text-red-700 mb-2 uppercase">先負 (Loss)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.loss.p1} onChange={(e)=>updateScoring('loss','p1',e.target.value)} className="w-full p-1 text-xs border rounded" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.loss.p2} onChange={(e)=>updateScoring('loss','p2',e.target.value)} className="w-full p-1 text-xs border rounded" />
                  </div>
                </div>
                <div className="bg-amber-50 p-3 rounded-xl border border-amber-100">
                  <p className="text-[10px] font-bold text-amber-700 mb-2 uppercase">和棋 (Draw)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.draw.p1} onChange={(e)=>updateScoring('draw','p1',e.target.value)} className="w-full p-1 text-xs border rounded" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.draw.p2} onChange={(e)=>updateScoring('draw','p2',e.target.value)} className="w-full p-1 text-xs border rounded" />
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-4 border-t">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold">桌次設定</h3>
              <div className="flex space-x-2">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} className="hidden" />
                <button type="button" onClick={()=>fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold">匯入 Excel</button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold">新增一桌</button>
              </div>
            </div>
            <div className="overflow-x-auto border rounded-2xl">
              <table className="w-full text-sm">
                <thead className="bg-slate-50">
                  <tr>
                    <th className="px-4 py-2">抬號</th>
                    <th className="px-4 py-2">先手 (編號/姓名)</th>
                    <th className="px-4 py-2">後手 (編號/姓名)</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((t, idx) => (
                    <tr key={idx}>
                      <td className="px-4 py-2 w-20"><input type="number" value={t.tableNumber} onChange={(e)=>{const n=[...tables];n[idx].tableNumber=parseInt(e.target.value);setTables(n)}} className="w-full p-1 border rounded" /></td>
                      <td className="px-4 py-2"><div className="flex space-x-1"><input type="text" value={t.player1?.id} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, id:e.target.value};setTables(n)}} className="w-20 p-1 border rounded text-xs" placeholder="ID" /><input type="text" value={t.player1?.name} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, name:e.target.value};setTables(n)}} className="w-full p-1 border rounded text-xs" placeholder="姓名" /></div></td>
                      <td className="px-4 py-2"><div className="flex space-x-1"><input type="text" value={t.player2?.id} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, id:e.target.value};setTables(n)}} className="w-20 p-1 border rounded text-xs" /><input type="text" value={t.player2?.name} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, name:e.target.value};setTables(n)}} className="w-full p-1 border rounded text-xs" /></div></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-lg">{editingSessionId ? '確認儲存' : '建立場次'}</button>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useMemo } from 'react';
import { MatchSession, UserRole, MatchStatus, TableMatch, GameResult, ScoringConfig } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface ResultsBoardProps {
  sessions: MatchSession[];
  userRole: UserRole;
  onRefresh: () => void;
}

type ViewMode = 'board' | 'table';

interface PlayerScore {
  id: string;
  name: string;
  points: number;
  winCount: number;
  lossCount: number;
  drawCount: number;
  matchCount: number;
}

const ResultsBoard: React.FC<ResultsBoardProps> = ({ sessions, userRole, onRefresh }) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('');
  const [viewMode, setViewMode] = useState<ViewMode>('board');
  const [editingTable, setEditingTable] = useState<{ sessionId: string, tableNumber: number } | null>(null);
  const [editResult, setEditResult] = useState<GameResult>(GameResult.PENDING);

  const selectedSession = sessions.find(s => s.id === selectedSessionId);
  const isAuthorized = userRole === UserRole.ADMIN || userRole === UserRole.REFEREE;

  // 計算所有選手積分
  const playerScores = useMemo(() => {
    if (!selectedSession) return [];
    const scoreMap: Record<string, PlayerScore> = {};
    const config: ScoringConfig = selectedSession.scoringConfig || {
      win: { p1: 1, p2: 0 },
      loss: { p1: 0, p2: 1 },
      draw: { p1: 0.5, p2: 0.5 }
    };

    selectedSession.tables.forEach(t => {
      // 初始化選手資料
      const ensurePlayer = (id: string, name: string) => {
        if (!scoreMap[id]) {
          scoreMap[id] = { id, name, points: 0, winCount: 0, lossCount: 0, drawCount: 0, matchCount: 0 };
        }
      };

      ensurePlayer(t.player1.id, t.player1.name);
      ensurePlayer(t.player2.id, t.player2.name);

      if (t.result === GameResult.PENDING) return;

      const p1 = scoreMap[t.player1.id];
      const p2 = scoreMap[t.player2.id];

      p1.matchCount++;
      p2.matchCount++;

      if (t.result === GameResult.WIN) {
        p1.points += config.win.p1;
        p2.points += config.win.p2;
        p1.winCount++;
        p2.lossCount++;
      } else if (t.result === GameResult.LOSS) {
        p1.points += config.loss.p1;
        p2.points += config.loss.p2;
        p1.lossCount++;
        p2.winCount++;
      } else if (t.result === GameResult.DRAW) {
        p1.points += config.draw.p1;
        p2.points += config.draw.p2;
        p1.drawCount++;
        p2.drawCount++;
      }
    });

    return Object.values(scoreMap).sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  }, [selectedSession]);

  const toggleStatus = (session: MatchSession, newStatus: MatchStatus) => {
    if (userRole !== UserRole.ADMIN) return;
    storageService.updateSession({ ...session, status: newStatus });
    onRefresh();
  };

  const handleEdit = (table: TableMatch) => {
    setEditingTable({ sessionId: selectedSessionId, tableNumber: table.tableNumber });
    setEditResult(table.result);
  };

  const saveEdit = () => {
    if (!selectedSession || !editingTable) return;
    const updatedTables = selectedSession.tables.map(t => {
      if (t.tableNumber === editingTable.tableNumber) {
        return { ...t, result: editResult, updatedAt: new Date().toISOString(), submittedBy: '後台修改' };
      }
      return t;
    });
    storageService.updateSession({ ...selectedSession, tables: updatedTables });
    setEditingTable(null);
    onRefresh();
  };

  const sortedTables = selectedSession ? [...selectedSession.tables].sort((a, b) => a.tableNumber - b.tableNumber) : [];
  const completedMatches = sortedTables.filter(t => t.result !== GameResult.PENDING);

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center space-x-2">
            <i className="fas fa-layer-group text-indigo-500"></i>
            <label className="font-bold text-gray-700">比賽場次</label>
          </div>
          {selectedSession && (
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button 
                onClick={() => setViewMode('board')} 
                className={`flex items-center space-x-2 px-4 py-1.5 rounded-lg text-xs font-bold transition ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                <i className="fas fa-th-large"></i><span>看板模式</span>
              </button>
              <button 
                onClick={() => setViewMode('table')} 
                className={`flex items-center space-x-2 px-4 py-1.5 rounded-lg text-xs font-bold transition ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                <i className="fas fa-list-ol"></i><span>表格積分</span>
              </button>
            </div>
          )}
        </div>
        <div className="flex flex-wrap gap-2 mt-4">
          {sessions.map(s => (
            <button key={s.id} onClick={() => setSelectedSessionId(s.id)} className={`px-5 py-2.5 rounded-xl text-base font-bold border-2 transition-all ${selectedSessionId === s.id ? 'bg-indigo-600 text-white border-indigo-600 shadow-md scale-105' : 'bg-white text-gray-600 border-gray-100 hover:border-indigo-200'}`}>{s.title}</button>
          ))}
        </div>
      </div>

      {selectedSession ? (
        <div className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-xl shadow-md border-l-4 border-indigo-500">
            <div>
              <h2 className="text-2xl font-bold text-gray-800">{selectedSession.title}</h2>
              <p className="text-xs text-gray-500">建立：{new Date(selectedSession.createdAt).toLocaleString()}</p>
            </div>
            <div className="flex items-center space-x-3">
              <span className={`px-3 py-1 rounded-full text-sm font-bold ${selectedSession.status === MatchStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{selectedSession.status === MatchStatus.OPEN ? '● 開放中' : '● 已截止'}</span>
              {userRole === UserRole.ADMIN && (
                <div className="flex bg-gray-100 p-1 rounded-lg">
                  <button onClick={() => toggleStatus(selectedSession, MatchStatus.OPEN)} className={`px-3 py-1 rounded-md text-xs font-bold ${selectedSession.status === MatchStatus.OPEN ? 'bg-white text-green-600 shadow-sm' : 'text-gray-400'}`}>開放</button>
                  <button onClick={() => toggleStatus(selectedSession, MatchStatus.CLOSED)} className={`px-3 py-1 rounded-md text-xs font-bold ${selectedSession.status === MatchStatus.CLOSED ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400'}`}>截止</button>
                </div>
              )}
            </div>
          </div>

          {viewMode === 'board' ? (
            <>
              {completedMatches.length > 0 && (
                <div className="bg-indigo-50 border border-indigo-100 rounded-xl p-5 shadow-sm">
                  <h3 className="text-xs font-bold text-indigo-700 uppercase tracking-wider mb-4 flex items-center">
                    <i className="fas fa-poll-h mr-2"></i> 已產生成績摘要 ({completedMatches.length})
                  </h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {completedMatches.map(t => (
                      <div key={t.tableNumber} className="bg-white p-4 rounded-xl shadow-sm border border-indigo-100 flex items-center justify-between min-w-[200px]">
                        <div className="flex flex-col min-w-0 flex-1">
                          <span className="font-bold text-indigo-600 text-xs">抬號 {t.tableNumber}</span>
                          <div className="flex items-center space-x-1 mt-1">
                            <span className="text-slate-800 text-base font-black whitespace-nowrap">{t.player1.name}</span>
                            <span className="text-[10px] text-indigo-400 font-bold">#{t.player1.id}</span>
                          </div>
                        </div>
                        <span className={`mx-3 font-black px-3 py-1.5 rounded text-lg ${t.result === GameResult.WIN ? 'bg-green-100 text-green-700' : t.result === GameResult.LOSS ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{t.result}</span>
                        <div className="flex flex-col min-w-0 flex-1 text-right">
                          <span className="text-xs opacity-0">.</span>
                          <div className="flex items-center space-x-1 justify-end mt-1">
                            <span className="text-slate-800 text-base font-black whitespace-nowrap">{t.player2.name}</span>
                            <span className="text-[10px] text-indigo-400 font-bold">#{t.player2.id}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {sortedTables.map(table => (
                  <div key={table.tableNumber} className="bg-white rounded-xl shadow-sm border hover:shadow-md transition overflow-hidden">
                    <div className="bg-gray-50 px-4 py-2 border-b flex justify-between items-center"><span className="font-bold text-indigo-600">第 {table.tableNumber} 桌</span></div>
                    <div className="p-4 space-y-4">
                      <div className="flex items-center justify-between text-center">
                        <div className="flex-1"><p className="text-xs text-gray-500">先手</p><p className="font-bold text-gray-800">{table.player1.name}</p><p className="text-[10px] text-indigo-500 font-black">#{table.player1.id}</p></div>
                        <div className="px-4 text-gray-300 italic font-light">vs</div>
                        <div className="flex-1"><p className="text-xs text-gray-500">後手</p><p className="font-bold text-gray-800">{table.player2.name}</p><p className="text-[10px] text-indigo-500 font-black">#{table.player2.id}</p></div>
                      </div>
                      <div className="flex items-center justify-between pt-2 border-t border-gray-50">
                        <div><span className="text-xs text-gray-400 block">結果</span><span className={`inline-block px-4 py-1 rounded-full text-lg font-black ${table.result === GameResult.WIN ? 'text-green-600' : table.result === GameResult.LOSS ? 'text-red-600' : table.result === GameResult.DRAW ? 'text-amber-600' : 'text-gray-300'}`}>{table.result}</span></div>
                        <div className="text-right">
                          {editingTable?.tableNumber === table.tableNumber ? (
                            <div className="flex flex-col space-y-1"><select value={editResult} onChange={(e)=>setEditResult(e.target.value as GameResult)} className="text-xs border rounded p-1">{Object.values(GameResult).map(r=><option key={r} value={r}>{r}</option>)}</select><div className="flex space-x-1"><button onClick={saveEdit} className="bg-indigo-500 text-white p-1 rounded text-[10px]">儲存</button><button onClick={()=>setEditingTable(null)} className="bg-gray-300 p-1 rounded text-[10px]">取消</button></div></div>
                          ) : (isAuthorized && selectedSession.status === MatchStatus.OPEN && <button onClick={()=>handleEdit(table)} className="text-indigo-500 text-xs font-semibold"><i className="fas fa-edit mr-1"></i>修改</button>)}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          ) : (
            <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead className="bg-slate-800 text-white font-bold uppercase tracking-wider">
                    <tr>
                      <th className="px-6 py-4">選手編號</th>
                      <th className="px-6 py-4">姓名</th>
                      <th className="px-6 py-4 text-center">總積分</th>
                      <th className="px-6 py-4">勝/負/和</th>
                      <th className="px-6 py-4">完賽桌數</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {playerScores.map(player => (
                      <tr key={player.id} className="hover:bg-slate-50 transition">
                        <td className="px-6 py-4 font-black text-indigo-600">#{player.id}</td>
                        <td className="px-6 py-4 font-bold text-gray-800">{player.name}</td>
                        <td className="px-6 py-4 text-center">
                          <span className="inline-block px-3 py-1 bg-amber-100 text-amber-700 rounded-full font-black text-lg">
                            {player.points}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex space-x-2 text-xs font-bold">
                            <span className="text-green-600">{player.winCount}勝</span>
                            <span className="text-red-500">{player.lossCount}負</span>
                            <span className="text-slate-400">{player.drawCount}和</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-gray-500 font-medium">
                          {player.matchCount} 局
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="text-center py-20 bg-white rounded-xl shadow-sm border border-gray-100"><i className="fas fa-hand-pointer text-5xl text-gray-200 mb-4 animate-bounce"></i><h3 className="text-xl font-medium text-gray-400">請選擇比賽場次</h3></div>
      )}
    </div>
  );
};

export default ResultsBoard;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult, ScoringConfig } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  sessions: MatchSession[];
  onSessionCreated: () => void;
}

const DEFAULT_SCORING: ScoringConfig = {
  win: { p1: 1, p2: 0 },
  loss: { p1: 0, p2: 1 },
  draw: { p1: 0.5, p2: 0.5 }
};

const AdminPanel: React.FC<AdminPanelProps> = ({ sessions, onSessionCreated }) => {
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [currentRefereePassword, setCurrentRefereePassword] = useState('');
  const [newRefereePassword, setNewRefereePassword] = useState('');
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [scoring, setScoring] = useState<ScoringConfig>(DEFAULT_SCORING);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    const settings = await storageService.getSettings();
    if (settings && settings.refereePassword) {
      setCurrentRefereePassword(settings.refereePassword);
    }
  };

  const toggleSessionStatus = async (session: MatchSession) => {
    const newStatus = session.status === MatchStatus.OPEN ? MatchStatus.CLOSED : MatchStatus.OPEN;
    await storageService.updateSession({ ...session, status: newStatus });
  };

  const handleUpdatePassword = async () => {
    if (!newRefereePassword) return alert('請輸入新密碼');
    if (newRefereePassword.length < 4) return alert('密碼長度建議至少 4 位');
    setIsUpdatingPassword(true);
    try {
      await storageService.updateRefereePassword(newRefereePassword);
      alert('密碼已更新');
      setCurrentRefereePassword(newRefereePassword);
      setNewRefereePassword('');
    } catch (e) {
      alert('更新失敗');
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    if (names.length > 0) {
      setReferees(prev => {
        const nextReferees = [...prev];
        names.forEach(name => {
          if (!nextReferees.includes(name)) nextReferees.push(name);
        });
        return nextReferees;
      });
      setRefereeInput('');
    }
  };

  const removeReferee = (name: string) => {
    setReferees(referees.filter(r => r !== name));
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: parseInt(row['抬號'] || row['桌號'] || row['Table'] || (idx + 1)),
          player1: { 
            id: String(row['先手編號'] || row['先手ID'] || row['P1 ID'] || ''), 
            name: String(row['先手姓名'] || row['P1 Name'] || '') 
          },
          player2: { 
            id: String(row['後手編號'] || row['後手ID'] || row['P2 ID'] || ''), 
            name: String(row['後手姓名'] || row['P2 Name'] || '') 
          },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportExcel = (session: MatchSession) => {
    const exportData = session.tables.map(t => {
      let p1Score = 0;
      let p2Score = 0;
      if (t.result === GameResult.WIN) {
        p1Score = session.scoringConfig?.win.p1 ?? 1;
        p2Score = session.scoringConfig?.win.p2 ?? 0;
      } else if (t.result === GameResult.LOSS) {
        p1Score = session.scoringConfig?.loss.p1 ?? 0;
        p2Score = session.scoringConfig?.loss.p2 ?? 1;
      } else if (t.result === GameResult.DRAW) {
        p1Score = session.scoringConfig?.draw.p1 ?? 0.5;
        p2Score = session.scoringConfig?.draw.p2 ?? 0.5;
      }

      return {
        '抬號': t.tableNumber,
        '先手編號': t.player1.id,
        '先手姓名': t.player1.name,
        '先手得分': t.result !== GameResult.PENDING ? p1Score : '',
        '後手編號': t.player2.id,
        '後手姓名': t.player2.name,
        '後手得分': t.result !== GameResult.PENDING ? p2Score : '',
        '結果': t.result,
        '送出裁判': t.submittedBy || '',
        '更新時間': t.updatedAt ? new Date(t.updatedAt).toLocaleString() : ''
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '比賽結果');
    XLSX.writeFile(workbook, `${session.title}_比賽結果.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入標題');
    if (referees.length === 0) return alert('請至少輸入一位裁判人員');

    const sessionData = {
      title,
      referees,
      scoringConfig: scoring,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      } as MatchSession);
      alert('場次已建立');
    }
    resetForm();
    onSessionCreated();
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees || []);
    setScoring(session.scoringConfig || DEFAULT_SCORING);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null); setScoring(DEFAULT_SCORING);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const updateScoring = (outcome: keyof ScoringConfig, side: 'p1' | 'p2', value: string) => {
    const num = parseFloat(value) || 0;
    setScoring(prev => ({
      ...prev,
      [outcome]: { ...prev[outcome], [side]: num }
    }));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { tableNumber: nextNum, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      <section className="bg-white rounded-2xl shadow-sm border border-red-100 overflow-hidden">
        <div className="bg-red-50 px-6 py-4 border-b border-red-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-red-800 flex items-center">
            <i className="fas fa-user-shield mr-2"></i>系統權限管理
          </h2>
        </div>
        <div className="p-6">
          <div className="max-w-md space-y-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">當前裁判密碼</p>
                <p className="text-2xl font-black text-slate-700 tracking-widest">{currentRefereePassword}</p>
              </div>
              <div className="bg-white p-2 rounded-lg shadow-sm"><i className="fas fa-key text-amber-500 text-xl"></i></div>
            </div>
            <div className="flex space-x-2">
              <input type="text" value={newRefereePassword} onChange={(e) => setNewRefereePassword(e.target.value)} className="flex-grow px-4 py-2 border rounded-xl" placeholder="新密碼..." />
              <button onClick={handleUpdatePassword} disabled={isUpdatingPassword} className="bg-red-600 text-white px-6 rounded-xl font-bold">確認更改</button>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center"><i className="fas fa-tasks text-indigo-500 mr-2"></i>場次管理</h2>
          <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">共 {sessions.length} 場</span>
        </div>
        <div className="divide-y divide-gray-100">
          {sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <button onClick={() => toggleSessionStatus(session)} className={`mt-2 px-3 py-1 rounded-full text-xs font-bold text-white ${session.status === MatchStatus.OPEN ? 'bg-green-500' : 'bg-red-500'}`}>
                  {session.status === MatchStatus.OPEN ? '開放中' : '已截止'}
                </button>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => handleExportExcel(session)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="匯出 Excel">
                  <i className="fas fa-file-excel text-xl"></i>
                </button>
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition" title="修改"><i className="fas fa-edit text-xl"></i></button>
                <button onClick={() => storageService.deleteSession(session.id)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-lg transition" title="刪除"><i className="fas fa-trash text-xl"></i></button>
              </div>
            </div>
          ))}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8"><i className="fas fa-plus-circle text-indigo-500 mr-3"></i>{editingSessionId ? '編輯' : '建立'}場次</h2>
        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} className="w-full px-4 py-3 border rounded-xl shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none transition" placeholder="例：2024 夏季賽" />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">裁判名單 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={refereeInput} 
                  onChange={(e) => setRefereeInput(e.target.value)} 
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addReferee())}
                  className="flex-grow px-4 py-3 border rounded-xl shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                  placeholder="輸入姓名並按新增" 
                />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-slate-700 transition shadow-md">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 pt-2">
                {referees.map(r => (
                  <span key={r} className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {r}
                    <button type="button" onClick={() => removeReferee(r)} className="ml-2 hover:text-red-500">
                      <i className="fas fa-times-circle"></i>
                    </button>
                  </span>
                ))}
              </div>
            </div>

            <div className="space-y-4 lg:col-span-2">
              <label className="text-sm font-bold text-slate-600 flex items-center">
                <i className="fas fa-calculator mr-2 text-indigo-400"></i>計分權重設定 (先手/後手得分)
              </label>
              <div className="grid grid-cols-3 gap-4">
                <div className="bg-green-50 p-3 rounded-xl border border-green-100">
                  <p className="text-[10px] font-bold text-green-700 mb-2 uppercase">先勝 (Win)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.win.p1} onChange={(e)=>updateScoring('win','p1',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="先" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.win.p2} onChange={(e)=>updateScoring('win','p2',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="後" title="後手得分" />
                  </div>
                </div>
                <div className="bg-red-50 p-3 rounded-xl border border-red-100">
                  <p className="text-[10px] font-bold text-red-700 mb-2 uppercase">先負 (Loss)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.loss.p1} onChange={(e)=>updateScoring('loss','p1',e.target.value)} className="w-full p-1 text-xs border rounded" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.loss.p2} onChange={(e)=>updateScoring('loss','p2',e.target.value)} className="w-full p-1 text-xs border rounded" title="後手得分" />
                  </div>
                </div>
                <div className="bg-amber-50 p-3 rounded-xl border border-amber-100">
                  <p className="text-[10px] font-bold text-amber-700 mb-2 uppercase">和棋 (Draw)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.draw.p1} onChange={(e)=>updateScoring('draw','p1',e.target.value)} className="w-full p-1 text-xs border rounded" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.draw.p2} onChange={(e)=>updateScoring('draw','p2',e.target.value)} className="w-full p-1 text-xs border rounded" title="後手得分" />
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-4 border-t">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-slate-800">桌次與對手設定</h3>
              <div className="flex space-x-2">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} className="hidden" />
                <button type="button" onClick={()=>fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold shadow-sm hover:bg-emerald-100 transition">匯入 Excel</button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold shadow-sm hover:bg-indigo-100 transition">新增一桌</button>
              </div>
            </div>
            <div className="overflow-x-auto border rounded-2xl shadow-sm">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr className="text-left text-slate-500 font-bold uppercase">
                    <th className="px-4 py-3 w-20">抬號</th>
                    <th className="px-4 py-3">先手 (編號/姓名)</th>
                    <th className="px-4 py-3">後手 (編號/姓名)</th>
                    <th className="px-4 py-3 w-16 text-center">刪</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((t, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-2 w-20"><input type="number" value={t.tableNumber} onChange={(e)=>{const n=[...tables];n[idx].tableNumber=parseInt(e.target.value);setTables(n)}} className="w-full p-2 border rounded-lg focus:ring-1 focus:ring-indigo-400 outline-none" /></td>
                      <td className="px-4 py-2">
                        <div className="flex space-x-1">
                          <input type="text" value={t.player1?.id} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, id:e.target.value};setTables(n)}} className="w-20 p-2 border rounded-lg text-xs" placeholder="ID" />
                          <input type="text" value={t.player1?.name} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, name:e.target.value};setTables(n)}} className="w-full p-2 border rounded-lg text-xs" placeholder="姓名" />
                        </div>
                      </td>
                      <td className="px-4 py-2">
                        <div className="flex space-x-1">
                          <input type="text" value={t.player2?.id} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, id:e.target.value};setTables(n)}} className="w-20 p-2 border rounded-lg text-xs" placeholder="ID" />
                          <input type="text" value={t.player2?.name} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, name:e.target.value};setTables(n)}} className="w-full p-2 border rounded-lg text-xs" placeholder="姓名" />
                        </div>
                      </td>
                      <td className="px-4 py-2 text-center">
                        <button type="button" onClick={() => {
                          const n = tables.filter((_, i) => i !== idx);
                          setTables(n);
                        }} className="text-red-400 hover:text-red-600 p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition active:scale-95">
            {editingSessionId ? '確認儲存修改' : '建立場次'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useMemo } from 'react';
import { MatchSession, UserRole, MatchStatus, TableMatch, GameResult, ScoringConfig } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface ResultsBoardProps {
  sessions: MatchSession[];
  userRole: UserRole;
  onRefresh: () => void;
}

type ViewMode = 'board' | 'table';

interface PlayerScore {
  id: string;
  name: string;
  points: number;
  winCount: number;
  lossCount: number;
  drawCount: number;
  matchCount: number;
}

const ResultsBoard: React.FC<ResultsBoardProps> = ({ sessions, userRole, onRefresh }) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('');
  const [viewMode, setViewMode] = useState<ViewMode>('board');
  const [editingTable, setEditingTable] = useState<{ sessionId: string, tableNumber: number } | null>(null);
  const [editResult, setEditResult] = useState<GameResult>(GameResult.PENDING);

  const selectedSession = sessions.find(s => s.id === selectedSessionId);
  const isAuthorized = userRole === UserRole.ADMIN || userRole === UserRole.REFEREE;

  const getMatchPoints = (table: TableMatch, session: MatchSession) => {
    if (table.result === GameResult.PENDING) return { p1: 0, p2: 0 };
    const config = session.scoringConfig || {
      win: { p1: 1, p2: 0 },
      loss: { p1: 0, p2: 1 },
      draw: { p1: 0.5, p2: 0.5 }
    };
    if (table.result === GameResult.WIN) return config.win;
    if (table.result === GameResult.LOSS) return config.loss;
    if (table.result === GameResult.DRAW) return config.draw;
    return { p1: 0, p2: 0 };
  };

  // 計算所有選手積分
  const playerScores = useMemo(() => {
    if (!selectedSession) return [];
    const scoreMap: Record<string, PlayerScore> = {};
    const config: ScoringConfig = selectedSession.scoringConfig || {
      win: { p1: 1, p2: 0 },
      loss: { p1: 0, p2: 1 },
      draw: { p1: 0.5, p2: 0.5 }
    };

    selectedSession.tables.forEach(t => {
      // 初始化選手資料
      const ensurePlayer = (id: string, name: string) => {
        if (!scoreMap[id]) {
          scoreMap[id] = { id, name, points: 0, winCount: 0, lossCount: 0, drawCount: 0, matchCount: 0 };
        }
      };

      ensurePlayer(t.player1.id, t.player1.name);
      ensurePlayer(t.player2.id, t.player2.name);

      if (t.result === GameResult.PENDING) return;

      const p1 = scoreMap[t.player1.id];
      const p2 = scoreMap[t.player2.id];

      p1.matchCount++;
      p2.matchCount++;

      if (t.result === GameResult.WIN) {
        p1.points += config.win.p1;
        p2.points += config.win.p2;
        p1.winCount++;
        p2.lossCount++;
      } else if (t.result === GameResult.LOSS) {
        p1.points += config.loss.p1;
        p2.points += config.loss.p2;
        p1.lossCount++;
        p2.winCount++;
      } else if (t.result === GameResult.DRAW) {
        p1.points += config.draw.p1;
        p2.points += config.draw.p2;
        p1.drawCount++;
        p2.drawCount++;
      }
    });

    return Object.values(scoreMap).sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  }, [selectedSession]);

  const toggleStatus = (session: MatchSession, newStatus: MatchStatus) => {
    if (userRole !== UserRole.ADMIN) return;
    storageService.updateSession({ ...session, status: newStatus });
    onRefresh();
  };

  const handleEdit = (table: TableMatch) => {
    setEditingTable({ sessionId: selectedSessionId, tableNumber: table.tableNumber });
    setEditResult(table.result);
  };

  const saveEdit = () => {
    if (!selectedSession || !editingTable) return;
    const updatedTables = selectedSession.tables.map(t => {
      if (t.tableNumber === editingTable.tableNumber) {
        return { ...t, result: editResult, updatedAt: new Date().toISOString(), submittedBy: '後台修改' };
      }
      return t;
    });
    storageService.updateSession({ ...selectedSession, tables: updatedTables });
    setEditingTable(null);
    onRefresh();
  };

  const sortedTables = selectedSession ? [...selectedSession.tables].sort((a, b) => a.tableNumber - b.tableNumber) : [];
  const completedMatches = sortedTables.filter(t => t.result !== GameResult.PENDING);

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center space-x-2">
            <i className="fas fa-layer-group text-indigo-500"></i>
            <label className="font-bold text-gray-700">比賽場次</label>
          </div>
          {selectedSession && (
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button 
                onClick={() => setViewMode('board')} 
                className={`flex items-center space-x-2 px-4 py-1.5 rounded-lg text-xs font-bold transition ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                <i className="fas fa-th-large"></i><span>看板模式</span>
              </button>
              <button 
                onClick={() => setViewMode('table')} 
                className={`flex items-center space-x-2 px-4 py-1.5 rounded-lg text-xs font-bold transition ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                <i className="fas fa-list-ol"></i><span>表格積分</span>
              </button>
            </div>
          )}
        </div>
        <div className="flex flex-wrap gap-2 mt-4">
          {sessions.map(s => (
            <button key={s.id} onClick={() => setSelectedSessionId(s.id)} className={`px-5 py-2.5 rounded-xl text-base font-bold border-2 transition-all ${selectedSessionId === s.id ? 'bg-indigo-600 text-white border-indigo-600 shadow-md scale-105' : 'bg-white text-gray-600 border-gray-100 hover:border-indigo-200'}`}>{s.title}</button>
          ))}
        </div>
      </div>

      {selectedSession ? (
        <div className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-xl shadow-md border-l-4 border-indigo-500">
            <div>
              <h2 className="text-2xl font-bold text-gray-800">{selectedSession.title}</h2>
              <p className="text-xs text-gray-500">建立：{new Date(selectedSession.createdAt).toLocaleString()}</p>
            </div>
            <div className="flex items-center space-x-3">
              <span className={`px-3 py-1 rounded-full text-sm font-bold ${selectedSession.status === MatchStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{selectedSession.status === MatchStatus.OPEN ? '● 開放中' : '● 已截止'}</span>
              {userRole === UserRole.ADMIN && (
                <div className="flex bg-gray-100 p-1 rounded-lg">
                  <button onClick={() => toggleStatus(selectedSession, MatchStatus.OPEN)} className={`px-3 py-1 rounded-md text-xs font-bold ${selectedSession.status === MatchStatus.OPEN ? 'bg-white text-green-600 shadow-sm' : 'text-gray-400'}`}>開放</button>
                  <button onClick={() => toggleStatus(selectedSession, MatchStatus.CLOSED)} className={`px-3 py-1 rounded-md text-xs font-bold ${selectedSession.status === MatchStatus.CLOSED ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400'}`}>截止</button>
                </div>
              )}
            </div>
          </div>

          {viewMode === 'board' ? (
            <>
              {completedMatches.length > 0 && (
                <div className="bg-indigo-50 border border-indigo-100 rounded-xl p-5 shadow-sm">
                  <h3 className="text-xs font-bold text-indigo-700 uppercase tracking-wider mb-4 flex items-center">
                    <i className="fas fa-poll-h mr-2"></i> 已產生成績摘要 ({completedMatches.length})
                  </h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {completedMatches.map(t => {
                      const pts = getMatchPoints(t, selectedSession);
                      return (
                        <div key={t.tableNumber} className="bg-white p-4 rounded-xl shadow-sm border border-indigo-100 flex items-center justify-between min-w-[200px]">
                          <div className="flex flex-col min-w-0 flex-1">
                            <span className="font-bold text-indigo-600 text-[10px]">抬號 {t.tableNumber}</span>
                            <div className="flex items-center space-x-1 mt-1">
                              <span className="text-slate-800 text-sm font-black whitespace-nowrap">{t.player1.name}</span>
                              <span className="bg-green-100 text-green-600 text-[9px] px-1 rounded font-bold">+{pts.p1}</span>
                            </div>
                          </div>
                          <span className={`mx-3 font-black px-2 py-1 rounded text-sm whitespace-nowrap ${t.result === GameResult.WIN ? 'bg-green-100 text-green-700' : t.result === GameResult.LOSS ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{t.result}</span>
                          <div className="flex flex-col min-w-0 flex-1 text-right">
                            <span className="text-[10px] text-gray-300">.</span>
                            <div className="flex items-center space-x-1 justify-end mt-1">
                              <span className="bg-blue-100 text-blue-600 text-[9px] px-1 rounded font-bold">+{pts.p2}</span>
                              <span className="text-slate-800 text-sm font-black whitespace-nowrap">{t.player2.name}</span>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {sortedTables.map(table => {
                  const pts = getMatchPoints(table, selectedSession);
                  return (
                    <div key={table.tableNumber} className="bg-white rounded-xl shadow-sm border hover:shadow-md transition overflow-hidden">
                      <div className="bg-gray-50 px-4 py-2 border-b flex justify-between items-center"><span className="font-bold text-indigo-600">第 {table.tableNumber} 桌</span></div>
                      <div className="p-4 space-y-4">
                        <div className="flex items-center justify-between text-center">
                          <div className="flex-1">
                            <p className="text-xs text-gray-500">先手</p>
                            <p className="font-bold text-gray-800">{table.player1.name}</p>
                            <div className="flex items-center justify-center space-x-1">
                              <span className="text-[10px] text-indigo-500 font-black">#{table.player1.id}</span>
                              {table.result !== GameResult.PENDING && <span className="text-[10px] bg-green-50 text-green-600 px-1 rounded font-bold">+{pts.p1}分</span>}
                            </div>
                          </div>
                          <div className="px-4 text-gray-300 italic font-light">vs</div>
                          <div className="flex-1">
                            <p className="text-xs text-gray-500">後手</p>
                            <p className="font-bold text-gray-800">{table.player2.name}</p>
                            <div className="flex items-center justify-center space-x-1">
                              <span className="text-[10px] text-indigo-500 font-black">#{table.player2.id}</span>
                              {table.result !== GameResult.PENDING && <span className="text-[10px] bg-blue-50 text-blue-600 px-1 rounded font-bold">+{pts.p2}分</span>}
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center justify-between pt-2 border-t border-gray-50">
                          <div><span className="text-xs text-gray-400 block">結果</span><span className={`inline-block px-4 py-1 rounded-full text-lg font-black ${table.result === GameResult.WIN ? 'text-green-600' : table.result === GameResult.LOSS ? 'text-red-600' : table.result === GameResult.DRAW ? 'text-amber-600' : 'text-gray-300'}`}>{table.result}</span></div>
                          <div className="text-right">
                            {editingTable?.tableNumber === table.tableNumber ? (
                              <div className="flex flex-col space-y-1"><select value={editResult} onChange={(e)=>setEditResult(e.target.value as GameResult)} className="text-xs border rounded p-1">{Object.values(GameResult).map(r=><option key={r} value={r}>{r}</option>)}</select><div className="flex space-x-1"><button onClick={saveEdit} className="bg-indigo-500 text-white p-1 rounded text-[10px]">儲存</button><button onClick={()=>setEditingTable(null)} className="bg-gray-300 p-1 rounded text-[10px]">取消</button></div></div>
                            ) : (isAuthorized && selectedSession.status === MatchStatus.OPEN && <button onClick={()=>handleEdit(table)} className="text-indigo-500 text-xs font-semibold hover:underline"><i className="fas fa-edit mr-1"></i>修改</button>)}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          ) : (
            <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead className="bg-slate-800 text-white font-bold uppercase tracking-wider">
                    <tr>
                      <th className="px-6 py-4">選手編號</th>
                      <th className="px-6 py-4">姓名</th>
                      <th className="px-6 py-4 text-center">總積分</th>
                      <th className="px-6 py-4">勝/負/和</th>
                      <th className="px-6 py-4">完賽桌數</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {playerScores.map(player => (
                      <tr key={player.id} className="hover:bg-slate-50 transition">
                        <td className="px-6 py-4 font-black text-indigo-600">#{player.id}</td>
                        <td className="px-6 py-4 font-bold text-gray-800">{player.name}</td>
                        <td className="px-6 py-4 text-center">
                          <span className="inline-block px-3 py-1 bg-amber-100 text-amber-700 rounded-full font-black text-lg">
                            {player.points}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex space-x-2 text-xs font-bold">
                            <span className="text-green-600">{player.winCount}勝</span>
                            <span className="text-red-500">{player.lossCount}負</span>
                            <span className="text-slate-400">{player.drawCount}和</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-gray-500 font-medium">
                          {player.matchCount} 局
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="text-center py-20 bg-white rounded-xl shadow-sm border border-gray-100"><i className="fas fa-hand-pointer text-5xl text-gray-200 mb-4 animate-bounce"></i><h3 className="text-xl font-medium text-gray-400">請選擇比賽場次</h3></div>
      )}
    </div>
  );
};

export default ResultsBoard;

import React, { useState, useEffect } from 'react';
import { MatchSession, MatchStatus, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface RefereePanelProps {
  sessions: MatchSession[];
  onResultSubmitted: () => void;
}

const STORAGE_NAME_KEY = 'mrms_remembered_referee_name';

const RefereePanel: React.FC<RefereePanelProps> = ({ sessions, onResultSubmitted }) => {
  const [refereeName, setRefereeName] = useState('');
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [selectedTableNumber, setSelectedTableNumber] = useState<number | ''>('');
  const [result, setResult] = useState<GameResult>(GameResult.PENDING);

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const currentTable = currentSession?.tables.find(t => t.tableNumber === selectedTableNumber);

  // 初始化載入記憶的姓名
  useEffect(() => {
    const savedName = localStorage.getItem(STORAGE_NAME_KEY);
    if (savedName) setRefereeName(savedName);
  }, []);

  useEffect(() => {
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  }, [selectedSessionId]);

  const handleNameSelect = (name: string) => {
    setRefereeName(name);
    localStorage.setItem(STORAGE_NAME_KEY, name);
  };

  const switchIdentity = () => {
    if (window.confirm('確定要切換裁判身份嗎？')) {
      setRefereeName('');
      localStorage.removeItem(STORAGE_NAME_KEY);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentSession) return alert('請先選擇比賽場次');
    if (!refereeName) return alert('請先選擇您的姓名');
    if (currentSession.status !== MatchStatus.OPEN) return alert('此場次已截止回報資料');
    if (selectedTableNumber === '') return alert('請選擇桌號');
    if (result === GameResult.PENDING) return alert('請點選勝負結果');

    const updatedTables = currentSession.tables.map(t => {
      if (t.tableNumber === selectedTableNumber) {
        return {
          ...t,
          result,
          submittedBy: refereeName,
          updatedAt: new Date().toISOString()
        };
      }
      return t;
    });

    storageService.updateSession({
      ...currentSession,
      tables: updatedTables
    });

    onResultSubmitted();
    alert('結果已成功同步更新！');
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  };

  // 檢查當前選取的姓名是否在場次的名單內
  const isNameInPool = currentSession?.referees.includes(refereeName);

  return (
    <div className="max-w-xl mx-auto space-y-6">
      <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-50 overflow-hidden">
        <div className="flex justify-between items-start mb-8">
          <h2 className="text-2xl font-black text-gray-800 flex items-center">
            <i className="fas fa-clipboard-check text-emerald-500 mr-2"></i>
            裁判結果回報
          </h2>
          {refereeName && (
             <div className="flex flex-col items-end">
               <span className="text-[10px] font-bold text-gray-400 uppercase">目前裁判</span>
               <div className="flex items-center space-x-2">
                 <span className="font-bold text-emerald-600">{refereeName}</span>
                 <button onClick={switchIdentity} className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 hover:bg-red-50 hover:text-red-500 transition">
                   切換身份
                 </button>
               </div>
             </div>
          )}
        </div>

        <div className="space-y-8">
          {/* 1. 比賽場次選擇 (按鈕) */}
          <section>
            <label className="block text-sm font-bold text-gray-600 mb-3 flex items-center">
              <span className="w-6 h-6 bg-slate-100 rounded-full flex items-center justify-center text-[10px] mr-2">1</span>
              選擇比賽場次
            </label>
            <div className="flex flex-wrap gap-2">
              {sessions.map(s => (
                <button
                  key={s.id}
                  type="button"
                  onClick={() => setSelectedSessionId(s.id)}
                  className={`px-4 py-2.5 rounded-xl text-[16px] font-bold transition-all border-2 ${
                    selectedSessionId === s.id
                      ? 'bg-emerald-600 text-white border-emerald-600 shadow-md ring-2 ring-emerald-100'
                      : 'bg-white text-gray-500 border-gray-100 hover:border-emerald-200'
                  }`}
                >
                  {s.title}
                  {s.status === MatchStatus.CLOSED && <span className="ml-1 opacity-60">(止)</span>}
                </button>
              ))}
            </div>
          </section>

          {/* 2. 姓名選取 (若無記憶時才顯示) */}
          {selectedSessionId && currentSession && (!refereeName || !isNameInPool) && (
            <section className="animate-in fade-in slide-in-from-top-4">
              <label className="block text-sm font-bold text-gray-600 mb-3 flex items-center">
                <span className="w-6 h-6 bg-slate-100 rounded-full flex items-center justify-center text-[10px] mr-2">2</span>
                您的姓名
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {currentSession.referees.map(r => (
                  <button
                    key={r}
                    type="button"
                    onClick={() => handleNameSelect(r)}
                    className="px-4 py-3 bg-white border border-gray-100 rounded-xl font-bold text-gray-700 hover:bg-emerald-50 hover:border-emerald-200 transition text-[16px]"
                  >
                    {r}
                  </button>
                ))}
              </div>
            </section>
          )}

          {/* 3. 桌號選擇 (僅顯示桌號數字，精簡網格) */}
          {selectedSessionId && refereeName && isNameInPool && (
            <section className="animate-in fade-in slide-in-from-top-4">
              <label className="block text-sm font-bold text-gray-600 mb-3 flex items-center">
                <span className="w-6 h-6 bg-slate-100 rounded-full flex items-center justify-center text-[10px] mr-2">2</span>
                選擇桌號
              </label>
              {/* 移除內部滾動條 max-h-60 overflow-y-auto */}
              <div className="grid grid-cols-4 sm:grid-cols-5 gap-2 p-1">
                {currentSession.tables.map(t => (
                  <button
                    key={t.tableNumber}
                    type="button"
                    onClick={() => setSelectedTableNumber(t.tableNumber)}
                    className={`py-3 rounded-xl transition-all border-2 flex items-center justify-center ${
                      selectedTableNumber === t.tableNumber
                        ? 'bg-emerald-600 text-white border-emerald-600 shadow-md scale-105'
                        : t.result !== GameResult.PENDING 
                          ? 'bg-gray-100 text-gray-400 border-gray-100 cursor-default opacity-50'
                          : 'bg-white text-gray-600 border-gray-100 hover:border-emerald-300 hover:bg-emerald-50'
                    }`}
                  >
                    <span className="text-[18px] font-black">{t.tableNumber}</span>
                  </button>
                ))}
              </div>
              <p className="text-[10px] text-gray-400 mt-2 text-center">※ 淺灰色桌號代表已有結果，仍可點擊修改</p>
            </section>
          )}

          {/* 4. 結果回報區 */}
          {currentTable && (
            <form onSubmit={handleSubmit} className="animate-in zoom-in duration-300 space-y-6 pt-4 border-t border-slate-50">
              <div className="bg-slate-50 p-6 rounded-2xl border border-dashed border-slate-200">
                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-4 text-center">正在登錄 第 {currentTable.tableNumber} 桌 結果</p>
                <div className="flex items-center justify-between text-center gap-2">
                  <div className="flex-1">
                    <p className="text-xs text-indigo-500 font-bold mb-1">#{currentTable.player1.id}</p>
                    <p className="font-black text-gray-800 text-xl">{currentTable.player1.name}</p>
                    <p className="text-[10px] text-gray-400 mt-1">先手</p>
                  </div>
                  <div className="px-2 text-slate-300 font-light italic text-xl">VS</div>
                  <div className="flex-1">
                    <p className="text-xs text-indigo-500 font-bold mb-1">#{currentTable.player2.id}</p>
                    <p className="font-black text-gray-800 text-xl">{currentTable.player2.name}</p>
                    <p className="text-[10px] text-gray-400 mt-1">後手</p>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-center text-sm font-bold text-gray-600 mb-4">比分結果 (先手狀態)</label>
                <div className="grid grid-cols-3 gap-3">
                  {[GameResult.WIN, GameResult.LOSS, GameResult.DRAW].map(res => (
                    <button
                      key={res}
                      type="button"
                      onClick={() => setResult(res)}
                      className={`py-5 rounded-2xl font-black text-xl border-4 transition-all ${
                        result === res 
                          ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg scale-105' 
                          : 'bg-white text-gray-400 border-gray-100 hover:border-emerald-200 hover:text-emerald-500'
                      }`}
                    >
                      {res}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                type="submit"
                disabled={currentSession?.status === MatchStatus.CLOSED}
                className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 ${
                  currentSession?.status === MatchStatus.CLOSED 
                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed shadow-none'
                    : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-100'
                }`}
              >
                <i className="fas fa-check-circle"></i>
                <span>{currentSession?.status === MatchStatus.CLOSED ? '目前已截止傳送' : '確認送出結果'}</span>
              </button>
            </form>
          )}
        </div>
      </div>

      <div className="text-center">
        <p className="text-[10px] text-gray-300">
          <i className="fas fa-history mr-1"></i> 
          本裝置已鎖定為裁判身份：{refereeName || '未選取'}
        </p>
      </div>
    </div>
  );
};

export default RefereePanel;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult, ScoringConfig } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  sessions: MatchSession[];
  onSessionCreated: () => void;
}

const DEFAULT_SCORING: ScoringConfig = {
  win: { p1: 1, p2: 0 },
  loss: { p1: 0, p2: 1 },
  draw: { p1: 0.5, p2: 0.5 }
};

const AdminPanel: React.FC<AdminPanelProps> = ({ sessions, onSessionCreated }) => {
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [currentRefereePassword, setCurrentRefereePassword] = useState('');
  const [newRefereePassword, setNewRefereePassword] = useState('');
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [scoring, setScoring] = useState<ScoringConfig>(DEFAULT_SCORING);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    const settings = await storageService.getSettings();
    if (settings && settings.refereePassword) {
      setCurrentRefereePassword(settings.refereePassword);
    }
  };

  const toggleSessionStatus = async (session: MatchSession) => {
    const newStatus = session.status === MatchStatus.OPEN ? MatchStatus.CLOSED : MatchStatus.OPEN;
    await storageService.updateSession({ ...session, status: newStatus });
  };

  const handleUpdatePassword = async () => {
    if (!newRefereePassword) return alert('請輸入新密碼');
    if (newRefereePassword.length < 4) return alert('密碼長度建議至少 4 位');
    setIsUpdatingPassword(true);
    try {
      await storageService.updateRefereePassword(newRefereePassword);
      alert('密碼已更新');
      setCurrentRefereePassword(newRefereePassword);
      setNewRefereePassword('');
    } catch (e) {
      alert('更新失敗');
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    if (names.length > 0) {
      setReferees(prev => {
        const nextReferees = [...prev];
        names.forEach(name => {
          if (!nextReferees.includes(name)) nextReferees.push(name);
        });
        return nextReferees;
      });
      setRefereeInput('');
    }
  };

  const removeReferee = (name: string) => {
    setReferees(referees.filter(r => r !== name));
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: parseInt(row['抬號'] || row['桌號'] || row['Table'] || (idx + 1)),
          player1: { 
            id: String(row['先手編號'] || row['先手ID'] || row['P1 ID'] || ''), 
            name: String(row['先手姓名'] || row['P1 Name'] || '') 
          },
          player2: { 
            id: String(row['後手編號'] || row['後手ID'] || row['P2 ID'] || ''), 
            name: String(row['後手姓名'] || row['P2 Name'] || '') 
          },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportExcel = (session: MatchSession) => {
    const exportData = session.tables.map(t => {
      let p1Score = 0;
      let p2Score = 0;
      if (t.result === GameResult.WIN) {
        p1Score = session.scoringConfig?.win.p1 ?? 1;
        p2Score = session.scoringConfig?.win.p2 ?? 0;
      } else if (t.result === GameResult.LOSS) {
        p1Score = session.scoringConfig?.loss.p1 ?? 0;
        p2Score = session.scoringConfig?.loss.p2 ?? 1;
      } else if (t.result === GameResult.DRAW) {
        p1Score = session.scoringConfig?.draw.p1 ?? 0.5;
        p2Score = session.scoringConfig?.draw.p2 ?? 0.5;
      }

      return {
        '抬號': t.tableNumber,
        '先手編號': t.player1.id,
        '先手姓名': t.player1.name,
        '先手得分': t.result !== GameResult.PENDING ? p1Score : '',
        '後手編號': t.player2.id,
        '後手姓名': t.player2.name,
        '後手得分': t.result !== GameResult.PENDING ? p2Score : '',
        '結果': t.result,
        '送出裁判': t.submittedBy || '',
        '更新時間': t.updatedAt ? new Date(t.updatedAt).toLocaleString() : ''
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '對賽紀錄');
    XLSX.writeFile(workbook, `${session.title}_對賽紀錄.xlsx`);
  };

  const handleExportExcelSummary = (session: MatchSession) => {
    const scoreMap: Record<string, { id: string, name: string, points: number, win: number, loss: number, draw: number, total: number }> = {};
    const config = session.scoringConfig || DEFAULT_SCORING;

    session.tables.forEach(t => {
      const ensurePlayer = (id: string, name: string) => {
        if (!scoreMap[id]) scoreMap[id] = { id, name, points: 0, win: 0, loss: 0, draw: 0, total: 0 };
      };
      ensurePlayer(t.player1.id, t.player1.name);
      ensurePlayer(t.player2.id, t.player2.name);

      if (t.result === GameResult.PENDING) return;

      const p1 = scoreMap[t.player1.id];
      const p2 = scoreMap[t.player2.id];
      p1.total++; p2.total++;

      if (t.result === GameResult.WIN) {
        p1.points += config.win.p1; p2.points += config.win.p2;
        p1.win++; p2.loss++;
      } else if (t.result === GameResult.LOSS) {
        p1.points += config.loss.p1; p2.points += config.loss.p2;
        p1.loss++; p2.win++;
      } else if (t.result === GameResult.DRAW) {
        p1.points += config.draw.p1; p2.points += config.draw.p2;
        p1.draw++; p2.draw++;
      }
    });

    const exportData = Object.values(scoreMap)
      .sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }))
      .map(p => ({
        '選手編號': p.id,
        '姓名': p.name,
        '總積分': p.points,
        '勝': p.win,
        '負': p.loss,
        '和': p.draw,
        '完賽桌數': p.total
      }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '積分總表');
    XLSX.writeFile(workbook, `${session.title}_積分總表.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入標題');
    if (referees.length === 0) return alert('請至少輸入一位裁判人員');

    const sessionData = {
      title,
      referees,
      scoringConfig: scoring,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      } as MatchSession);
      alert('場次已建立');
    }
    resetForm();
    onSessionCreated();
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees || []);
    setScoring(session.scoringConfig || DEFAULT_SCORING);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null); setScoring(DEFAULT_SCORING);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const updateScoring = (outcome: keyof ScoringConfig, side: 'p1' | 'p2', value: string) => {
    const num = parseFloat(value) || 0;
    setScoring(prev => ({
      ...prev,
      [outcome]: { ...prev[outcome], [side]: num }
    }));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { tableNumber: nextNum, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      <section className="bg-white rounded-2xl shadow-sm border border-red-100 overflow-hidden">
        <div className="bg-red-50 px-6 py-4 border-b border-red-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-red-800 flex items-center">
            <i className="fas fa-user-shield mr-2"></i>系統權限管理
          </h2>
        </div>
        <div className="p-6">
          <div className="max-w-md space-y-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">當前裁判密碼</p>
                <p className="text-2xl font-black text-slate-700 tracking-widest">{currentRefereePassword}</p>
              </div>
              <div className="bg-white p-2 rounded-lg shadow-sm"><i className="fas fa-key text-amber-500 text-xl"></i></div>
            </div>
            <div className="flex space-x-2">
              <input type="text" value={newRefereePassword} onChange={(e) => setNewRefereePassword(e.target.value)} className="flex-grow px-4 py-2 border rounded-xl" placeholder="新密碼..." />
              <button onClick={handleUpdatePassword} disabled={isUpdatingPassword} className="bg-red-600 text-white px-6 rounded-xl font-bold">確認更改</button>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center"><i className="fas fa-tasks text-indigo-500 mr-2"></i>場次管理</h2>
          <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">共 {sessions.length} 場</span>
        </div>
        <div className="divide-y divide-gray-100">
          {sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <button onClick={() => toggleSessionStatus(session)} className={`mt-2 px-3 py-1 rounded-full text-xs font-bold text-white ${session.status === MatchStatus.OPEN ? 'bg-green-500' : 'bg-red-500'}`}>
                  {session.status === MatchStatus.OPEN ? '開放中' : '已截止'}
                </button>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => handleExportExcel(session)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="匯出 對賽紀錄">
                  <i className="fas fa-file-excel text-xl"></i>
                </button>
                <button onClick={() => handleExportExcelSummary(session)} className="p-2.5 text-amber-600 hover:bg-amber-50 rounded-lg transition" title="匯出 積分總表 (依編號排序)">
                  <i className="fas fa-list-ol text-xl"></i>
                </button>
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition" title="修改"><i className="fas fa-edit text-xl"></i></button>
                <button onClick={() => storageService.deleteSession(session.id)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-lg transition" title="刪除"><i className="fas fa-trash text-xl"></i></button>
              </div>
            </div>
          ))}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8"><i className="fas fa-plus-circle text-indigo-500 mr-3"></i>{editingSessionId ? '編輯' : '建立'}場次</h2>
        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} className="w-full px-4 py-3 border rounded-xl shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none transition" placeholder="例：2024 夏季賽" />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">裁判名單 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={refereeInput} 
                  onChange={(e) => setRefereeInput(e.target.value)} 
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addReferee())}
                  className="flex-grow px-4 py-3 border rounded-xl shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                  placeholder="輸入姓名並按新增" 
                />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-slate-700 transition shadow-md">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 pt-2">
                {referees.map(r => (
                  <span key={r} className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {r}
                    <button type="button" onClick={() => removeReferee(r)} className="ml-2 hover:text-red-500">
                      <i className="fas fa-times-circle"></i>
                    </button>
                  </span>
                ))}
              </div>
            </div>

            <div className="space-y-4 lg:col-span-2">
              <label className="text-sm font-bold text-slate-600 flex items-center">
                <i className="fas fa-calculator mr-2 text-indigo-400"></i>計分權重設定 (先手/後手得分)
              </label>
              <div className="grid grid-cols-3 gap-4">
                <div className="bg-green-50 p-3 rounded-xl border border-green-100">
                  <p className="text-[10px] font-bold text-green-700 mb-2 uppercase">先勝 (Win)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.win.p1} onChange={(e)=>updateScoring('win','p1',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="先" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.win.p2} onChange={(e)=>updateScoring('win','p2',e.target.value)} className="w-full p-1 text-xs border rounded" placeholder="後" title="後手得分" />
                  </div>
                </div>
                <div className="bg-red-50 p-3 rounded-xl border border-red-100">
                  <p className="text-[10px] font-bold text-red-700 mb-2 uppercase">先負 (Loss)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.loss.p1} onChange={(e)=>updateScoring('loss','p1',e.target.value)} className="w-full p-1 text-xs border rounded" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.loss.p2} onChange={(e)=>updateScoring('loss','p2',e.target.value)} className="w-full p-1 text-xs border rounded" title="後手得分" />
                  </div>
                </div>
                <div className="bg-amber-50 p-3 rounded-xl border border-amber-100">
                  <p className="text-[10px] font-bold text-amber-700 mb-2 uppercase">和棋 (Draw)</p>
                  <div className="flex items-center space-x-1">
                    <input type="number" step="0.5" value={scoring.draw.p1} onChange={(e)=>updateScoring('draw','p1',e.target.value)} className="w-full p-1 text-xs border rounded" title="先手得分" />
                    <span className="text-gray-300">/</span>
                    <input type="number" step="0.5" value={scoring.draw.p2} onChange={(e)=>updateScoring('draw','p2',e.target.value)} className="w-full p-1 text-xs border rounded" title="後手得分" />
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-4 border-t">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-slate-800">桌次與對手設定</h3>
              <div className="flex space-x-2">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} className="hidden" />
                <button type="button" onClick={()=>fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold shadow-sm hover:bg-emerald-100 transition">匯入 Excel</button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold shadow-sm hover:bg-indigo-100 transition">新增一桌</button>
              </div>
            </div>
            <div className="overflow-x-auto border rounded-2xl shadow-sm">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr className="text-left text-slate-500 font-bold uppercase">
                    <th className="px-4 py-3 w-20">抬號</th>
                    <th className="px-4 py-3">先手 (編號/姓名)</th>
                    <th className="px-4 py-3">後手 (編號/姓名)</th>
                    <th className="px-4 py-3 w-16 text-center">刪</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((t, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-2 w-20"><input type="number" value={t.tableNumber} onChange={(e)=>{const n=[...tables];n[idx].tableNumber=parseInt(e.target.value);setTables(n)}} className="w-full p-2 border rounded-lg focus:ring-1 focus:ring-indigo-400 outline-none" /></td>
                      <td className="px-4 py-2">
                        <div className="flex space-x-1">
                          <input type="text" value={t.player1?.id} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, id:e.target.value};setTables(n)}} className="w-20 p-2 border rounded-lg text-xs" placeholder="ID" />
                          <input type="text" value={t.player1?.name} onChange={(e)=>{const n=[...tables];n[idx].player1={...n[idx].player1!, name:e.target.value};setTables(n)}} className="w-full p-2 border rounded-lg text-xs" placeholder="姓名" />
                        </div>
                      </td>
                      <td className="px-4 py-2">
                        <div className="flex space-x-1">
                          <input type="text" value={t.player2?.id} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, id:e.target.value};setTables(n)}} className="w-20 p-2 border rounded-lg text-xs" placeholder="ID" />
                          <input type="text" value={t.player2?.name} onChange={(e)=>{const n=[...tables];n[idx].player2={...n[idx].player2!, name:e.target.value};setTables(n)}} className="w-full p-2 border rounded-lg text-xs" placeholder="姓名" />
                        </div>
                      </td>
                      <td className="px-4 py-2 text-center">
                        <button type="button" onClick={() => {
                          const n = tables.filter((_, i) => i !== idx);
                          setTables(n);
                        }} className="text-red-400 hover:text-red-600 p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition active:scale-95">
            {editingSessionId ? '確認儲存修改' : '建立場次'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;
